package com.printflow.customer;
import com.printflow.identity.StaffPrincipal;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;
import java.util.*;import org.springframework.core.env.Environment;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController
public class WorkController {
 public record Message(@NotBlank @Size(max=3000) String body){}
 public record Resolution(@Min(0) long revision,@NotBlank @Pattern(regexp="REJECTED|REMOVED") String kind,@NotBlank @Size(min=20,max=1000) String message){}
 private final com.printflow.identity.ProjectNotifications notifications;private final Payments payments;private final JdbcTemplate db;private final Environment env;private final com.printflow.shared.RequestLimits limits;
 public WorkController(com.printflow.identity.ProjectNotifications notifications,Payments payments,JdbcTemplate db,Environment env,com.printflow.shared.RequestLimits limits){this.notifications=notifications;this.payments=payments;this.db=db;this.env=env;this.limits=limits;}
 private Map<String,Object> scoped(StaffPrincipal u,UUID id,boolean write){var rows=db.queryForList("select id,public_id,status,revision,designer_id,assigned_staff_id,customer_user_id,product_code,quantity,closure_kind,closure_message from enquiries where id=?"+(write?" for update":""),id);if(rows.isEmpty())throw new NoSuchElementException();var e=rows.getFirst();boolean allowed=switch(u.role()){case "OWNER"->true;case "CUSTOMER"->u.id().equals(e.get("customer_user_id"));case "DESIGNER"->!"NEW".equals(e.get("status"))&&u.id().equals(e.get("designer_id"));case "SALES"->!"NEW".equals(e.get("status"))&&u.id().equals(e.get("assigned_staff_id"));default->false;};if(!allowed)throw new NoSuchElementException();return e;}
 @GetMapping("/api/v1/design/enquiries/{id}/work") @Transactional(readOnly=true)
 public ResponseEntity<?> view(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id){var e=scoped(u,id,false);boolean accepted=db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ACCEPTED')",Boolean.class,id);var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("publicId",e.get("public_id"));result.put("productCode",e.get("product_code"));result.put("quantity",e.get("quantity"));result.put("status",e.get("status"));result.put("liveWork",accepted);result.put("closureMessage",e.get("closure_message"));
  var proof=db.queryForList("select p.revision,d.action,a.state,q.state='ACCEPTED' as current_agreement from proof_revisions p join design_artifacts a on a.id=p.artifact_id join quote_versions q on q.id=p.quote_id left join proof_decisions d on d.proof_id=p.id where p.enquiry_id=? order by p.revision desc limit 1",id);String design=proof.isEmpty()?"Preparing design":!Boolean.TRUE.equals(proof.getFirst().get("current_agreement"))?"New agreement needs proof":!"CLEAN".equals(proof.getFirst().get("state"))?"Awaiting file clearance":"APPROVE".equals(proof.getFirst().get("action"))?"Proof approved":"REJECT".equals(proof.getFirst().get("action"))?"Proof rejected": "REQUEST_CHANGES".equals(proof.getFirst().get("action"))?"Designer changes requested":"Customer proof review";
  var fulfil=db.queryForList("select state,issue_open,delivered_at from fulfilment_work where enquiry_id=?",id);var production=db.queryForList("select stage,hold_reason from production_jobs where enquiry_id=?",id);String productionLabel=production.isEmpty()?"In production":production.getFirst().get("hold_reason")!=null?"Production on hold":switch(production.getFirst().get("stage").toString()){case "QUEUED"->"Queued for printing";case "PRINTING"->"Printing";case "FINISHING"->"Finishing";case "QC"->"Quality check";default->"Production completed";};String operation=fulfil.isEmpty()?"NOT_STARTED":fulfil.getFirst().get("state").toString();
  var latestQuote=db.queryForList("select state from quote_versions where enquiry_id=? order by version desc limit 1",id);String amendmentState="NONE";if(accepted&&!latestQuote.isEmpty()){String state=latestQuote.getFirst().get("state").toString();if(state.equals("ISSUED")||state.equals("CHANGES_REQUESTED"))amendmentState=state;}
  String proofDecision=proof.isEmpty()||proof.getFirst().get("action")==null?"NONE":proof.getFirst().get("action").toString();String proofScan=proof.isEmpty()?"NONE":proof.getFirst().get("state").toString();boolean proofForCurrentAgreement=!proof.isEmpty()&&Boolean.TRUE.equals(proof.getFirst().get("current_agreement"));boolean productionHold=!production.isEmpty()&&production.getFirst().get("hold_reason")!=null;boolean deliveryIssueOpen=!fulfil.isEmpty()&&Boolean.TRUE.equals(fulfil.getFirst().get("issue_open"));
  result.put("workflow",Map.of("quotationAccepted",accepted,"amendmentState",amendmentState,"proofDecision",proofDecision,"proofScanState",proofScan,"proofForCurrentAgreement",proofForCurrentAgreement,"paymentCode",payments.stageCode(id),"fulfilmentState",operation,"productionStage",production.isEmpty()?"NONE":production.getFirst().get("stage").toString(),"productionHold",productionHold,"deliveryIssueOpen",deliveryIssueOpen));
  result.put("stages",Map.of("quotation",accepted?"Accepted":"Awaiting acceptance","design",design,"production",operation.equals("NOT_STARTED")?"Not released":operation.equals("PRODUCTION")?productionLabel:"Production completed","payment",payments.stage(id),"delivery",operation.equals("IN_TRANSIT")?"In transit":operation.equals("DELIVERED")?"Delivered — 48-hour review":operation.equals("COMPLETED")?"Completed":operation.equals("READY")?"Ready for dispatch":"Not started"));
  result.put("designer",e.get("designer_id")==null?null:db.queryForObject("select coalesce(nullif(public_name,''),'Assigned designer') from staff_users where id=?",String.class,e.get("designer_id")));result.put("contact",Map.of("email",env.getProperty("APP_PUBLIC_SUPPORT_EMAIL",""),"phone",env.getProperty("APP_PUBLIC_SUPPORT_PHONE","")));result.put("mailConnected",false);result.put("emails",db.queryForList("select m.id,m.kind,m.subject,m.state,m.thread_phase,m.created_at from mail_outbox m join enquiries e on e.id=m.enquiry_id where m.enquiry_id=? and (?=false or lower(m.recipient)=lower(e.email)) order by m.created_at desc,m.id desc limit 100",id,u.role().equals("CUSTOMER")));
  result.put("logs",db.queryForList("select kind,message,created_at from (select kind,message,created_at from work_events where enquiry_id=? union all select 'REQUEST' as kind,'Enquiry received' as message,created_at from enquiries where id=? union all select 'PROOF' as kind,'Proof revision '||p.revision||' shared' as message,p.created_at from proof_revisions p where p.enquiry_id=? union all select 'PROOF' as kind,case when d.decision_source<>'PORTAL' then 'Staff recorded '||lower(d.decision_source)||' approval of proof revision ' when d.action='APPROVE' then 'Customer approved proof revision ' when d.action='REJECT' then 'Customer rejected proof revision ' else 'Customer requested changes to proof revision ' end||p.revision as message,d.created_at from proof_decisions d join proof_revisions p on p.id=d.proof_id where p.enquiry_id=?) history order by created_at desc limit 200",id,id,id,id));result.put("messages",db.queryForList("select id,author_role,channel,body,created_at from work_messages where enquiry_id=? order by created_at desc,id desc limit 100",id));return response(result);}
 @PostMapping("/api/v1/design/enquiries/{id}/work/messages") @Transactional public ResponseEntity<?> message(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Message input){var e=scoped(u,id,true);if("CLOSED".equals(e.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Closed work is read-only");if(!db.queryForObject("select exists(select 1 from quote_versions where enquiry_id=? and state='ACCEPTED')",Boolean.class,id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Accept a quotation before starting the work conversation");limits.require("work-message",u.id().toString(),60);UUID message=UUID.randomUUID();db.update("insert into work_messages(id,enquiry_id,actor_id,author_role,body) values(?,?,?,?,?)",message,id,u.id(),u.role().equals("CUSTOMER")?"CUSTOMER":"TEAM",input.body().trim());notifications.both(id,"MESSAGE",message,"New project message from "+(u.role().equals("CUSTOMER")?"the customer":"the team")+":\n\n"+input.body().trim());return response(Map.of("code","MESSAGE_SENT"));}
 @PostMapping("/api/v1/staff/enquiries/{id}/resolve") @Transactional public ResponseEntity<?> resolve(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Resolution input){if(input.kind().equals("REMOVED")&&!u.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the owner may remove an enquiry");if(!Set.of("OWNER","SALES").contains(u.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);var e=scoped(u,id,true);if("CLOSED".equals(e.get("status"))||((Number)e.get("revision")).longValue()!=input.revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Enquiry changed; refresh first");String message=input.message().trim();if(message.length()<20)throw new IllegalArgumentException("Give a meaningful customer-visible explanation");db.update("update enquiries set status='CLOSED',closure_kind=?,closure_message=?,next_action=null,follow_up_at=null,revision=revision+1,updated_at=now() where id=?",input.kind(),message,id);db.update("insert into enquiry_events(id,enquiry_id,event_type,from_status,to_status) values(?,?,?,?,'CLOSED')",UUID.randomUUID(),id,input.kind(),e.get("status"));db.update("insert into work_events(id,enquiry_id,actor_id,kind,message) values(?,?,?,?,?)",UUID.randomUUID(),id,u.id(),input.kind(),message);db.update("insert into lead_activities(id,enquiry_id,actor_id,action,details) values(?,?,?,?,?)",UUID.randomUUID(),id,u.id(),input.kind(),message);return response(Map.of("code",input.kind()));}
 private ResponseEntity<?> response(Object body){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);}
}
